@patch
def changes(self:Agent):
    "`{path: (before, after)}` for every file this turn's write tools actually moved."
    out = {}
    for p, was in self.before.items():
        now = self.host.text_at(p)
        if now is not None and now != was: out[p] = (was, now)
    return out

