_agent_record = Agent._record

@patch
def _record(self:Agent, f):
    wrapped = _agent_record(self, f)
    @functools.wraps(wrapped)
    def call(*a, **kw):
        run = current_run()
        if run is not None and run.cancelled:return 'Run cancelled; this tool call was not started.'
        return wrapped(*a, **kw)
    return call


